import {getClient} from './supabase-client.js';import {rows,invoke,runtimeError} from './services/runtime-service.js';import {markdown} from './vendor/markdown.js';
let options={};
export async function notificationCenter({modal,esc,toast}){try{const c=await getClient();const items=await rows(c.from('user_notifications').select('id,title,body,is_read,created_at').order('created_at',{ascending:false}).limit(60));modal('Bildirişlər',items.length?items.map(n=>`<article class="mini-note"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${esc(new Date(n.created_at).toLocaleString())}</small></article>`).join(''):'<p class="muted" style="margin-top:20px">Yeni bildiriş yoxdur. Xatırlatma seçimlərini hesabından aktivləşdirə bilərsən.</p>');const unread=items.filter(n=>!n.is_read).map(n=>n.id);if(unread.length)await rows(c.from('user_notifications').update({is_read:true}).in('id',unread));}catch(e){toast(runtimeError(e));}}
export async function activityCenter({modal,esc,toast}){try{const c=await getClient();const [jobs,materials,proposals]=await Promise.all([rows(c.from('jarvis_jobs').select('id,status,scheduled_at,last_error').order('scheduled_at',{ascending:false}).limit(50)),rows(c.from('prepared_materials').select('id,title,created_at').order('created_at',{ascending:false}).limit(30)),rows(c.from('jarvis_proposals').select('*').eq('confirmed',false).order('created_at',{ascending:false}).limit(20))]);modal('JARVIS fəaliyyətləri',`<h3 style="margin-top:20px">Təsdiq gözləyən təkliflər</h3>${proposals.length?proposals.map(p=>`<div class="mini-note"><p>${esc(p.summary)}</p><p>${esc(p.uncertainty)}</p><small>Təklif olunan vaxt: ${esc(p.suggested_time||'Müəyyən edilməyib')}</small><button class="text-btn" data-proposal="${p.id}">Vaxtı seç və təsdiqlə</button></div>`).join(''):'<p class="muted">Təklif yoxdur.</p>'}<h3 style="margin-top:20px">Hazırlanmış materiallar</h3>${materials.length?materials.map(m=>`<button class="history-item" data-material="${m.id}">${esc(m.title)} · ${esc(new Date(m.created_at).toLocaleDateString())}</button>`).join(''):'<p class="muted">Hələ material hazırlanmayıb.</p>'}<h3 style="margin-top:20px">İşlər</h3>${jobs.map(j=>`<div class="mini-note"><span>${esc(new Date(j.scheduled_at).toLocaleString())} · ${esc(j.status)}</span>${['scheduled','draft','retry'].includes(j.status)?`<button class="text-btn" data-cancel-job="${j.id}">Ləğv et</button>`:''}<small>${esc(j.last_error||'')}</small></div>`).join('')||'<p class="muted">Planlaşdırılmış iş yoxdur.</p>'}`);
document.querySelectorAll('[data-material]').forEach(b=>b.onclick=async()=>{const m=await rows(c.from('prepared_materials').select('title,content').eq('id',b.dataset.material).single());modal(esc(m.title),'<p class="format-help">AI tərəfindən hazırlanıb. Xarici mənbələrlə müstəqil yoxlanılmayıb; nümunə məsələlər ev tapşırığının həlli kimi təqdim edilmir.</p><div class="markdown">'+markdown(m.content)+'</div>');});document.querySelectorAll('[data-cancel-job]').forEach(b=>b.onclick=async()=>{try{await rows(c.from('jarvis_jobs').update({status:'cancelled'}).eq('id',b.dataset.cancelJob));toast('İş ləğv edildi.');b.disabled=true;}catch(e){toast(runtimeError(e));}});document.querySelectorAll('[data-proposal]').forEach(b=>b.onclick=()=>{const id=b.dataset.proposal;modal('Hazırlıq vaxtını təsdiqlə','<form id="confirm-schedule" class="form"><p>Bu vaxtda provayderə qeyd göndəriləcək və büdcən daxilində ödənişli hazırlıq sorğusu icra edilə bilər.</p><label>Başlama vaxtı (cihazın yerli vaxtı)<input type="datetime-local" name="time" required></label><button class="btn primary">Planlaşdırmanı təsdiq edirəm</button></form>');document.querySelector('#confirm-schedule').onsubmit=async e=>{e.preventDefault();try{await rows(c.rpc('confirm_jarvis',{proposal_id:id,run_at:new Date(new FormData(e.target).get('time')).toISOString()}));toast('Hazırlıq işi planlaşdırıldı.');document.querySelector('#modal').close();}catch(e){toast(runtimeError(e));}};});}catch(e){toast(runtimeError(e));}}
export async function analyzeNote(id,{toast,...h}){try{toast('İcazələr və büdcə yoxlanılır…');await invoke('jarvis',{noteId:id});toast('Təklif hazırdır. Vaxtı təsdiqləmək üçün fəaliyyətlərə bax.');await activityCenter({toast,...h});}catch(e){toast(runtimeError(e));}}
export async function attachAccountControls(container,user){const c=await getClient();let policy=await rows(c.from('ai_policy').select('*').eq('user_id',user.id).maybeSingle());if(!policy)policy={user_id:user.id,paid_consent:false,allow_fallback:false,memory_enabled:false,daily_usd:0,monthly_usd:0,daily_requests:0,monthly_requests:0,timezone:'Asia/Baku',daily_briefing:false,weekly_summary:false,push_enabled:false,movie_notifications:false};const section=document.createElement('section');section.className='runtime-preferences';section.innerHTML=`<h2>AI, büdcə və məxfilik</h2><p class="format-help">AI-yə göndərdiyin mesajlar, açıq razılıq verdiyin qeydlər və aktiv yaddaş seçilmiş Google, Anthropic və ya xAI xidmətinə ötürülür. Büdcə qiymət konfiqurasiyasına əsaslanan təxmini USD xərclərini məhdudlaşdırır. Yeni hesabda AI ödənişi, bildirişlər və yaddaş deaktivdir. Büdcə limitləri UTC günü və ayı üzrə yenilənir.</p><form id="ai-policy" class="form">${[['paid_consent','Məlumat ötürülməsini və limitlərim daxilində ödənişli AI istifadəsini təsdiqləyirəm'],['allow_fallback','Xəta olduqda limitim daxilində başqa provayderə keçidə icazə verirəm'],['memory_enabled','Təsdiqlədiyim yaddaşı AI cavablarına daxil et'],['notification_consent','Tətbiqdaxili xatırlatma və bildirişlərə razıyam'],['daily_briefing','Səhər saat 08:00-dan sonra gündəlik plan bildirişi'],['weekly_summary','Bazar günü 18:00-dan sonra həftəlik icmal'],['movie_notifications','Günün filmi haqqında bildiriş al'],['push_enabled','Bu cihaz üçün push bildirişinə abunə olmağa icazə verirəm']].map(([k,l])=>`<label class="row"><input type="checkbox" name="${k}" ${policy[k]?'checked':''}>${l}</label>`).join('')}<div class="budget-grid">${[['daily_usd','Günlük USD büdcəsi',100],['monthly_usd','Aylıq USD büdcəsi',1000],['daily_requests','Günlük sorğu limiti',1000],['monthly_requests','Aylıq sorğu limiti',10000]].map(([k,l,max])=>`<label>${l}<input name="${k}" type="number" min="0" max="${max}" step="${k.endsWith('usd')?'0.001':'1'}" value="${Number(policy[k])||0}" required></label>`).join('')}</div><label>Saat qurşağı<select name="timezone">${['Asia/Baku','Europe/Istanbul','UTC'].map(z=>`<option ${policy.timezone===z?'selected':''}>${z}</option>`).join('')}</select></label><button class="btn primary">Seçimləri saxla</button></form><div id="policy-status" role="status"></div><button class="btn" id="enable-push" style="margin-top:12px">Bu cihazda bildirişə abunə ol</button><button class="btn" id="disable-push">Bu cihazda abunəliyi dayandır</button><p class="format-help">iPhone-da dəstəklənən iOS versiyası və ana ekrana əlavə edilmiş PWA tələb oluna bilər. Dəstək yoxdursa tətbiqdaxili mərkəz işləyir. Bildiriş icazəsi yalnız bu düyməyə toxunanda soruşulur.</p><h2 style="margin-top:24px">Şəxsi yaddaş</h2><div id="memory-list"></div><form id="memory-form" class="form"><label>Başlıq<input name="label" maxlength="80" required></label><label>Yadda saxlanacaq məlumat<textarea name="content" maxlength="2000" required></textarea></label><button class="btn">Yaddaşa əlavə et</button></form><h2 style="margin-top:24px">Görünüş</h2><label>Tema<select id="theme-select"><option value="dark">Tünd navy</option><option value="light">Açıq lavanda</option></select></label>`;container.append(section);const status=text=>section.querySelector('#policy-status').textContent=text;let pushConfig=null;try{pushConfig=await invoke('push-subscription',{action:'config'});}catch{}if(!pushConfig?.supported){const button=section.querySelector('#enable-push');button.disabled=true;const hint=document.createElement('p');hint.className='format-help';hint.textContent=pushConfig?'Push server konfiqurasiyası tamamlanmayıb; tətbiqdaxili bildirişlər işləyir.':'Push xidməti hazırda əlçatan deyil; tətbiqdaxili bildiriş mərkəzindən istifadə et.';button.after(hint);}const esc=s=>String(s).replace(/[&<>"']/g,v=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[v]));
section.querySelector('#ai-policy').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const values={user_id:user.id,timezone:f.get('timezone')};for(const key of ['paid_consent','allow_fallback','memory_enabled','notification_consent','daily_briefing','weekly_summary','movie_notifications','push_enabled'])values[key]=f.has(key);for(const key of ['daily_usd','monthly_usd','daily_requests','monthly_requests'])values[key]=Number(f.get(key));try{await rows(c.from('ai_policy').upsert(values));await rows(c.from('ai_preferences').update({notifications_enabled:values.notification_consent}).eq('user_id',user.id));policy={...policy,...values};status('Seçimlər saxlanıldı.');}catch(e){status(runtimeError(e));}};
async function memories(){const values=await rows(c.from('ai_memory').select('*').order('created_at',{ascending:false}));section.querySelector('#memory-list').innerHTML=values.map(m=>`<div class="mini-note"><strong>${esc(m.label)}</strong><p>${esc(m.content)}</p><button class="text-btn" data-edit-memory="${m.id}">Redaktə et</button><button class="text-btn danger" data-delete-memory="${m.id}">Sil</button></div>`).join('')||'<p class="muted">Yaddaş boşdur.</p>';section.querySelectorAll('[data-delete-memory]').forEach(b=>b.onclick=async()=>{await rows(c.from('ai_memory').delete().eq('id',b.dataset.deleteMemory));await memories();});section.querySelectorAll('[data-edit-memory]').forEach(b=>b.onclick=()=>{const m=values.find(v=>v.id===b.dataset.editMemory);const form=section.querySelector('#memory-form');form.dataset.id=m.id;form.elements.label.value=m.label;form.elements.content.value=m.content;form.scrollIntoView({block:'center',behavior:'smooth'});});}
section.querySelector('#memory-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),value={user_id:user.id,label:f.get('label').trim(),content:f.get('content').trim()};try{if(e.target.dataset.id)await rows(c.from('ai_memory').update(value).eq('id',e.target.dataset.id));else await rows(c.from('ai_memory').insert(value));e.target.reset();delete e.target.dataset.id;await memories();}catch(e){status(runtimeError(e));}};await memories();const usage=await rows(c.rpc('my_usage'));const usageBox=document.createElement('section');usageBox.innerHTML='<h2>Bu ayın AI istifadəsi</h2><p class="muted">'+Number(usage.requests)+' sorğu cəhdi · '+Number(usage.tokens)+' token · təxmini USD '+Number(usage.usd).toFixed(6)+'</p><p class="format-help">Bu gün: USD '+Number(usage.daily_usd).toFixed(6)+'. Qeyri-müəyyən xərc qeydləri: '+Number(usage.uncertain)+'.</p>';section.append(usageBox);
const theme=section.querySelector('#theme-select');theme.value=document.documentElement.dataset.theme||'dark';theme.onchange=e=>{document.documentElement.dataset.theme=e.target.value;try{localStorage.setItem('astra-theme',e.target.value);}catch{}};
section.querySelector('#enable-push').onclick=async()=>{try{if(!policy.push_enabled||!policy.notification_consent){status('Əvvəl push razılığını seçib saxla.');return;}if(!('Notification'in window)||!('PushManager'in window)||!('serviceWorker'in navigator)){status('Bu brauzer push dəstəkləmir. Tətbiqdaxili bildirişlər əlçatandır.');return;}const config=pushConfig;if(!config?.supported||!config.publicKey){status('Push server konfiqurasiyası tamamlanmayıb.');return;}if(await Notification.requestPermission()!=='granted'){status('Brauzer bildiriş icazəsi verilmədi.');return;}const registration=await navigator.serviceWorker.ready;const key=Uint8Array.from(atob(config.publicKey.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await invoke('push-subscription',{action:'subscribe',subscription:subscription.toJSON(),consent:true});status('Bu cihaz abunə oldu.');}catch(e){status(runtimeError(e));}};section.querySelector('#disable-push').onclick=async()=>{try{const registration=await navigator.serviceWorker.ready,subscription=await registration.pushManager.getSubscription();if(subscription){await invoke('push-subscription',{action:'remove',endpoint:subscription.endpoint});await subscription.unsubscribe();}status('Bu cihazın abunəliyi dayandırıldı.');}catch(e){status(runtimeError(e));}};
}